WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT id, session_id, event_time, session_start_flag, burst_id FROM islands ORDER BY event_time DESC;
